function feePercentFrom(raw: string | undefined): number {
  if (raw === undefined || raw.trim() === '') return 10;
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0 || n > 100) {
    throw new Error(`CANCELLATION_FEE_PERCENT must be 0-100: ${raw}`);
  }
  return n;
}

switch (order.status) {
  case 'CART':
  case 'PAYMENT_FAILED':
    // 課金されていないことが確かな状態だけ、返金せずに取り消す
    order.status = 'CANCELLED';
    break;
  case 'PAID': {
    // 今のコードのまま（返金してから CANCELLED にして break）
    ...
  }
  default:
    // PENDING_PAYMENT は照合バッチが決着を付けるまで取り消さない
    throw new InvalidOrderStateError(order, 'cancelled');
}
